import { useDispatch, useSelector } from 'react-redux';
import './AboutMe.css'
import { editProfile, selectUser,editedProfile } from '../../../../store/slices/UserSlice';

const AboutMe = () => {
  
    const {profile} = useSelector(selectUser)
    const dispatch = useDispatch()
    
    const handlerSubmit = async (e) => {
      e.preventDefault()
      const [FirstName,LastName,Age,Bio,Location,Profession,Hobbies] = e.target
      const newUser = {
        id: profile.id,
        FirstName: FirstName.value,
        LastName: LastName.value,
        Age: Age.value,
        Bio: Bio.value,
        Location: Location.value,
        Profession: Profession.value,
        Hobbies: Hobbies.value,
        Image: profile.Image,
      }
      await fetch(`http://localhost:3005/Loged_User/${profile.id}`, {
        method: 'PATCH',
        body: JSON.stringify(newUser),
      })
      dispatch(editedProfile(newUser))
      
      
    }
    return (
      <div className="info">
        {
              <div className='user-info' key={profile.id}>
                <div className='user-name'>
                  <h3>{profile.first_name}</h3>
                  <h3>{profile.last_name}</h3>
                </div>
                <p><strong>Age:</strong> {profile.age}</p>
                <p><strong>Bio:</strong> {profile.bio}</p>
                <p><strong>Location:</strong> {profile.location}</p>
                <p><strong>Profession:</strong> {profile.profession}</p>
                <p><strong>Hobbie:</strong> {profile.hobbies}</p>
                <button 
                className='edit-profile-button' onClick={() => {
                  dispatch(editProfile())
                }}>Edit Profile</button>
              </div>
           }
        
      </div>
    
    );
}

export default AboutMe
